const response = $input.first().json;
const jobs = response?.data?.jobs || response?.jobs || [];
const studentSkills = ['React', 'JavaScript', 'Node.js', 'MongoDB', 'CSS', 'HTML', 'TypeScript', 'Python'];

const results = [];

for (const job of jobs) {
  const text = ((job.title || '') + ' ' + (job.description || '')).toLowerCase();
  const matched = [];

  for (const skill of studentSkills) {
    if (text.includes(skill.toLowerCase())) {
      matched.push(skill);
    }
  }

  const matchScore = Math.min(100, Math.round((matched.length / Math.min(studentSkills.length, 3)) * 100));

  const salaryText = job.salary_min
    ? `₹${Math.round(job.salary_min / 100000)} - ₹${Math.round(job.salary_max / 100000)} LPA`
    : 'Best in Industry';

  const telegramMsg = `🎯 *DheePath — New Job Match Found!*\n\n` +
    `🏢 *Company:* ${job.company?.display_name || 'Verified Tech Partner'}\n` +
    `💼 *Role:* ${job.title}\n` +
    `📍 *Location:* ${job.location?.display_name || 'India (Hybrid/Remote)'}\n` +
    `💰 *Salary:* ${salaryText}\n` +
    `⚡ *Skill Match:* ${matchScore}%\n` +
    `🛠 *Matched Skills:* ${matched.join(', ') || 'Core Developer Stack'}\n\n` +
    `👉 [Click Here to View & Apply](${job.redirect_url})`;

  const emailHtml = `<div style="font-family: Arial, sans-serif; max-width: 600px; padding: 24px; border: 1px solid #e2e8f0; border-radius: 12px; background: #ffffff;">` +
    `<h2 style="color: #0284c7; margin-top: 0;">🎯 DheePath — Live Job Match!</h2>` +
    `<p style="color: #475569; font-size: 15px;">Hi Parth, aapke verified skills ke hisaab se ek nayi high-match opening aayi hai:</p>` +
    `<div style="background: #f8fafc; padding: 18px; border-radius: 8px; margin: 18px 0; border-left: 4px solid #0284c7;">` +
    `<h3 style="margin-top: 0; color: #0f172a;">${job.title}</h3>` +
    `<p style="margin: 6px 0; color: #334155;"><b>🏢 Company:</b> ${job.company?.display_name || 'Top Tech Company'}</p>` +
    `<p style="margin: 6px 0; color: #334155;"><b>📍 Location:</b> ${job.location?.display_name || 'India'}</p>` +
    `<p style="margin: 6px 0; color: #334155;"><b>💰 Salary:</b> ${salaryText}</p>` +
    `<p style="margin: 6px 0;"><b>⚡ Skill Match:</b> <span style="color: #16a34a; font-weight: bold;">${matchScore}%</span></p>` +
    `<p style="margin: 6px 0; color: #64748b;"><b>🛠 Skills:</b> ${matched.join(', ') || 'Developer Fundamentals'}</p>` +
    `</div>` +
    `<a href="${job.redirect_url}" style="display: inline-block; padding: 12px 24px; background: #0284c7; color: #ffffff; text-decoration: none; border-radius: 6px; font-weight: bold; font-size: 15px;">👉 View & Apply Immediately</a>` +
    `<p style="color: #94a3b8; font-size: 12px; margin-top: 24px; border-top: 1px solid #f1f5f9; pt-3;">Sent automatically by DheePath Autonomous Telemetry Pipeline.</p>` +
    `</div>`;

  results.push({
    json: {
      title: job.title,
      company: job.company?.display_name || 'Tech Company',
      location: job.location?.display_name || 'India',
      salary: salaryText,
      matchScore,
      matchedSkills: matched.join(', '),
      applyUrl: job.redirect_url,
      alertMessage: telegramMsg,
      emailSubject: `🎯 DheePath Job Alert: ${job.title} at ${job.company?.display_name || 'Tech Company'} (${matchScore}% Match)`,
      emailHtml
    }
  });
}

return results;
